'use client';
import SignaturePad from 'signature_pad';
import { useEffect, useRef } from 'react';

export function {{component_name}}({ onSave }: { onSave: (dataUrl: string) => void }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const padRef = useRef<SignaturePad | null>(null);
  useEffect(() => { padRef.current = new SignaturePad(ref.current!); }, []);
  return (
    <div>
      <canvas ref={ref} width={400} height={160} style={{ border:'1px solid #ccc' }} />
      <button onClick={() => padRef.current?.clear()}>清除</button>
      <button onClick={() => onSave(padRef.current!.toDataURL('image/png'))}>儲存</button>
    </div>
  );
}
